from pysat.solvers import Glucose3
from pysat.card import CardEnc

# 4x4 Sudoku with block size 2
# Variables: x[i][v] where i is cell index (0-15), v is value (1-4)
# Cell i is at row r = i//4, col c = i%4

n = 4
cells = 16

# Create SAT solver
solver = Glucose3()

# Map: (cell, value) -> variable id
var = {}
vid = 1
for i in range(cells):
    for v in range(1, n+1):
        var[(i, v)] = vid
        vid += 1

# Each cell gets exactly one value
for i in range(cells):
    clause = [var[(i, v)] for v in range(1, n+1)]
    solver.add_clause(clause)
    # At most one: pairwise negative
    for v1 in range(1, n+1):
        for v2 in range(v1+1, n+1):
            solver.add_clause([-var[(i, v1)], -var[(i, v2)]])

# Each row has each value exactly once
for r in range(n):
    for v in range(1, n+1):
        clause = [var[(r*n + c, v)] for c in range(n)]
        solver.add_clause(clause)
        # At most one
        for c1 in range(n):
            for c2 in range(c1+1, n):
                solver.add_clause([-var[(r*n + c1, v)], -var[(r*n + c2, v)]])

# Each column has each value exactly once
for c in range(n):
    for v in range(1, n+1):
        clause = [var[(r*n + c, v)] for r in range(n)]
        solver.add_clause(clause)
        for r1 in range(n):
            for r2 in range(r1+1, n):
                solver.add_clause([-var[(r1*n + c, v)], -var[(r2*n + c, v)]])

# Each 2x2 block has each value exactly once
# Blocks: top-left corners at (0,0), (0,2), (2,0), (2,2)
blocks = [(0,0), (0,2), (2,0), (2,2)]
for br, bc in blocks:
    for v in range(1, n+1):
        cells_in_block = []
        for dr in range(2):
            for dc in range(2):
                r = br + dr
                c = bc + dc
                cells_in_block.append(r*n + c)
        clause = [var[(i, v)] for i in cells_in_block]
        solver.add_clause(clause)
        for idx1, i1 in enumerate(cells_in_block):
            for idx2, i2 in enumerate(cells_in_block):
                if idx1 < idx2:
                    solver.add_clause([-var[(i1, v)], -var[(i2, v)]])

# Fixed assignments
# x[7]=2, x[9]=1, x[12]=4
# Cell indices: 0-based
fixed = {7: 2, 9: 1, 12: 4}
for i, v in fixed.items():
    solver.add_clause([var[(i, v)]])

# Solve
result = solver.solve()
print("Satisfiable:", result)

if result:
    model = solver.get_model()
    # Extract solution
    solution = [0] * cells
    for i in range(cells):
        for v in range(1, n+1):
            if model[var[(i, v)] - 1] > 0:
                solution[i] = v
                break
    print("Solution:", solution)

    # Verify
    # Print grid
    for r in range(n):
        row = solution[r*n:(r+1)*n]
        print(row)

    # Check constraints
    # Rows
    for r in range(n):
        vals = [solution[r*n + c] for c in range(n)]
        assert sorted(vals) == [1,2,3,4], f"Row {r} invalid: {vals}"
    # Columns
    for c in range(n):
        vals = [solution[r*n + c] for r in range(n)]
        assert sorted(vals) == [1,2,3,4], f"Col {c} invalid: {vals}"
    # Blocks
    for br, bc in blocks:
        vals = []
        for dr in range(2):
            for dc in range(2):
                vals.append(solution[(br+dr)*n + (bc+dc)])
        assert sorted(vals) == [1,2,3,4], f"Block ({br},{bc}) invalid: {vals}"

    print("All constraints satisfied!")
else:
    print("UNSATISFIABLE")
